INSERT INTO `faqs` (`id`, `seq`, `q`, `a`) VALUES
  (1, 1, 'Is OroRuta free to use?', 'Yes, OroRuta is completely free. No account, subscription, or payment is required.'),
  (2, 2, 'Do I need to create an account?', 'No. OroRuta works as a guest app. Your saved routes and history are stored on your device using an anonymous device ID.'),
  (3, 3, 'Are jeepney locations tracked in real time?', 'No. OroRuta does not track jeepney positions. GPS is used only for your own location and navigation.'),
  (4, 4, 'Are the fares shown exact?', 'Fares are estimates based on the LTFRB minimum fare schedule (₱13.00 for the first 4 km, ₱1.80 per km thereafter). Actual fares may differ. Always check with official sources.'),
  (5, 5, 'What if my route is not found?', 'OroRuta currently covers jeepney routes within Cagayan de Oro City based on the CDO LPTRP. If your route is not found, try changing your starting location or destination, or browse all routes in the Routes tab.'),
  (6, 6, 'How accurate are the stop locations?', 'Stop locations are based on research data and are approximate. Exact positions on the ground may vary slightly. If you find an error, please use the "Report an Issue" feature.'),
  (7, 7, 'Can I use the app without GPS?', 'Yes. You can manually enter your starting location instead of using GPS. Route search, route details, and offline content all work without GPS.'),
  (8, 8, 'How do I save a route?', 'On any Route Details or Result screen, tap the bookmark icon to save the route. Saved routes appear in the Saved tab.'),
  (9, 9, 'What does \'Rerouted\' mean?', 'A Rerouted status means the jeepney currently follows a different path from its usual route, often due to road closures or construction. Check the related announcement for details.'),
  (10, 10, 'How do I report incorrect information?', 'Go to More > Report an Issue. Select the type of issue, describe it, and submit. Reports are reviewed before being treated as official.'),
  (11, 11, 'What are the supported languages?', 'OroRuta supports English, Cebuano (Bisaya), and Filipino. Change the language from More > Preferences > Language.'),
  (12, 12, 'Does OroRuta work offline?', 'Yes, partially. Download routes from the Route Information screen for offline access. Downloaded routes and the city map are available without internet.');
INSERT INTO `fare_rules` (`id`, `minimum`, `minimum_km`, `per_km`, `discount_rate`, `effective_from`, `is_current`) VALUES
  (1, '13.00', '4.00', '1.80', '0.200', '2024-01-01 00:00:00', 1);
INSERT INTO `help_topics` (`id`, `seq`, `title`, `body`) VALUES
  (1, 1, 'How OroRuta works', 'OroRuta is a jeepney route guide for Cagayan de Oro City. It helps you find jeepney routes, view route details, estimate fares, and navigate step-by-step using your phone\'s GPS. All data is based on the CDO LPTRP. No account is needed — the app works as a guest.'),
  (2, 2, 'How to search for a route', 'From the Home screen, tap "Where are you going?" to open the search. Enter your starting location (or use your GPS location) and your destination. Tap "Search Route" to see available jeepney routes. You can sort results by travel time, fare, walking distance, or number of transfers.'),
  (3, 3, 'How to read jeepney routes', 'Each route has a code (e.g., R3), a color, and shows the origin and destination. The status pill shows if the route is Active, Rerouted, Updated, or Temporary. Tap a route to see detailed stops: Terminals (T), Loading points (L), Unloading points (U), and Transfer points.'),
  (4, 4, 'GPS navigation', 'Tap "Start Navigation" on any route result to begin step-by-step navigation. The app uses your phone\'s GPS to track your position and auto-advance walking steps when you are within 30 meters of the next point. Jeepneys are not tracked — only your own location is used.'),
  (5, 5, 'Offline routes', 'You can download individual routes for offline use from the Route Information screen. Downloaded routes are available without internet. Go to More > Offline Routes to manage your downloads. The city map is also available for offline viewing once synced.');
